with latest as (select * from products qualify row_number() over (partition by category, brand order by launch_date nulls first, id) = 1) select case when cost >= 560 then 'HIGH' else 'LOW' end as cost_tier, count(distinct id) as distinct_ids, sum(cost) as total_cost, count_if(category = 'Home') as home_events, grouping_id() as gid from latest group by rollup (case when cost >= 560 then 'HIGH' else 'LOW' end) order by total_cost desc;
